"""Repositories for the todo application's persistent data."""

from abc import ABC, abstractmethod
from datetime import datetime
import sqlite3


def get_connection(database):
    connection = sqlite3.connect(database)
    connection.row_factory = sqlite3.Row
    return connection


class BaseRepository(ABC):
    """Small SQLite repository base with shared CRUD primitives."""

    table: str

    def __init__(self, database: str):
        self.database = database

    def _connect(self):
        return get_connection(self.database)

    def _execute(self, query, parameters=()):
        with self._connect() as connection:
            return connection.execute(query, parameters).fetchall()

    def get_by_id(self, record_id):
        rows = self._execute(f"SELECT * FROM {self.table} WHERE id = ?", (record_id,))
        return rows[0] if rows else None

    def list(self):
        return self._execute(f"SELECT * FROM {self.table}")

    def delete(self, record_id):
        with self._connect() as connection:
            cursor = connection.execute(f"DELETE FROM {self.table} WHERE id = ?", (record_id,))
            return cursor.rowcount > 0

    @abstractmethod
    def create(self, values):
        """Create one record and return its database representation."""

    @abstractmethod
    def update(self, record_id, values):
        """Update one record and return its database representation."""


class UserRepository(BaseRepository):
    table = "users"

    def create(self, values):
        with self._connect() as connection:
            cursor = connection.execute(
                "INSERT INTO users (username, password_hash) VALUES (?, ?)",
                (values["username"], values["password_hash"]),
            )
            return {"id": cursor.lastrowid, "username": values["username"]}

    def update(self, record_id, values):
        if not values:
            return self.get_by_id(record_id)
        assignments = ", ".join(f"{key} = ?" for key in values)
        parameters = [*values.values(), record_id]
        with self._connect() as connection:
            connection.execute(f"UPDATE users SET {assignments} WHERE id = ?", parameters)
        return self.get_by_id(record_id)

    def find_by_username(self, username):
        rows = self._execute("SELECT * FROM users WHERE username = ?", (username,))
        return rows[0] if rows else None

    def find_public_by_id(self, user_id):
        rows = self._execute("SELECT id, username FROM users WHERE id = ?", (user_id,))
        return rows[0] if rows else None


class TaskRepository(BaseRepository):
    table = "tasks"

    def create(self, values):
        with self._connect() as connection:
            cursor = connection.execute(
                "INSERT INTO tasks (title, status, created_at, owner_id) VALUES (?, 'pending', ?, ?)",
                (values["title"], values["created_at"], values["owner_id"]),
            )
            return {
                "id": cursor.lastrowid,
                "title": values["title"],
                "status": "pending",
                "created_at": values["created_at"],
            }

    def update(self, record_id, values):
        if values:
            assignments = ", ".join(f"{key} = ?" for key in values)
            parameters = [*values.values(), record_id]
            with self._connect() as connection:
                connection.execute(f"UPDATE tasks SET {assignments} WHERE id = ?", parameters)
        return self.get_by_id(record_id)

    def create_for_owner(self, title, owner_id):
        return self.create({
            "title": title,
            "created_at": datetime.utcnow().isoformat(),
            "owner_id": owner_id,
        })

    def list_for_owner(self, owner_id):
        rows = self._execute(
            "SELECT id, title, status, created_at FROM tasks "
            "WHERE owner_id = ? ORDER BY created_at DESC",
            (owner_id,),
        )
        return [dict(row) for row in rows]

    def get_for_owner(self, task_id, owner_id):
        rows = self._execute(
            "SELECT id, title, status, created_at FROM tasks WHERE id = ? AND owner_id = ?",
            (task_id, owner_id),
        )
        return dict(rows[0]) if rows else None

    def update_for_owner(self, task_id, owner_id, values):
        task = self.get_for_owner(task_id, owner_id)
        if task is None:
            return None
        if values:
            assignments = ", ".join(f"{key} = ?" for key in values)
            parameters = [*values.values(), task_id, owner_id]
            with self._connect() as connection:
                connection.execute(
                    f"UPDATE tasks SET {assignments} WHERE id = ? AND owner_id = ?",
                    parameters,
                )
        return self.get_for_owner(task_id, owner_id)


def initialize_database(database):
    """Create the schema and migrate databases created by older app versions."""
    with sqlite3.connect(database) as connection:
        connection.execute(
            "CREATE TABLE IF NOT EXISTS users ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  username TEXT NOT NULL UNIQUE,"
            "  password_hash TEXT NOT NULL"
            ")"
        )
        connection.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'done', 'completed')),"
            "  created_at TEXT NOT NULL,"
            "  owner_id INTEGER REFERENCES users(id)"
            ")"
        )
        columns = {row[1] for row in connection.execute("PRAGMA table_info(tasks)")}
        if "owner_id" not in columns:
            connection.execute("ALTER TABLE tasks ADD COLUMN owner_id INTEGER REFERENCES users(id)")
        schema = connection.execute(
            "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'tasks'"
        ).fetchone()[0]
        if "'completed'" not in schema:
            connection.execute("DROP INDEX IF EXISTS idx_tasks_owner_id")
            connection.execute("ALTER TABLE tasks RENAME TO tasks_old")
            connection.execute(
                "CREATE TABLE tasks ("
                "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
                "  title TEXT NOT NULL,"
                "  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'done', 'completed')),"
                "  created_at TEXT NOT NULL,"
                "  owner_id INTEGER REFERENCES users(id)"
                ")"
            )
            connection.execute(
                "INSERT INTO tasks (id, title, status, created_at, owner_id) "
                "SELECT id, title, status, created_at, owner_id FROM tasks_old"
            )
            connection.execute("DROP TABLE tasks_old")
        connection.execute("CREATE INDEX IF NOT EXISTS idx_tasks_owner_id ON tasks(owner_id)")

"""Minimal Flask Todo API."""

from flask import Flask, request, jsonify, g
from datetime import datetime
from functools import wraps
import base64
import binascii
import hashlib
import hmac
import json
import os
from sqlite3 import IntegrityError
from werkzeug.security import check_password_hash, generate_password_hash
from tasks import send_notification_email
from repositories import TaskRepository, UserRepository, get_connection, initialize_database

app = Flask(__name__)
DATABASE = os.environ.get("DATABASE", "todos.db")
app.config["JWT_SECRET"] = os.environ.get("JWT_SECRET", "development-secret-change-me")
JWT_LIFETIME_SECONDS = 3600
VALID_STATUSES = {"pending", "done", "completed"}


def get_db():
    return get_connection(DATABASE)


def init_db():
    initialize_database(DATABASE)


def create_user(username: str, password: str) -> dict:
    return UserRepository(DATABASE).create({
        "username": username,
        "password_hash": generate_password_hash(password),
    })


def find_user(username: str):
    return UserRepository(DATABASE).find_by_username(username)


def _b64encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).rstrip(b"=").decode("ascii")


def _b64decode(value: str) -> bytes:
    return base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))


def create_token(user_id: int) -> str:
    now = int(datetime.utcnow().timestamp())
    header = _b64encode(json.dumps({"alg": "HS256", "typ": "JWT"}, separators=(",", ":")).encode())
    payload = _b64encode(json.dumps({"sub": str(user_id), "iat": now, "exp": now + JWT_LIFETIME_SECONDS}, separators=(",", ":")).encode())
    signing_input = f"{header}.{payload}".encode("ascii")
    signature = hmac.new(app.config["JWT_SECRET"].encode("utf-8"), signing_input, hashlib.sha256).digest()
    return f"{header}.{payload}.{_b64encode(signature)}"


def decode_token(token: str) -> int:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("invalid token")
    signing_input = f"{parts[0]}.{parts[1]}".encode("ascii")
    expected = hmac.new(app.config["JWT_SECRET"].encode("utf-8"), signing_input, hashlib.sha256).digest()
    if not hmac.compare_digest(expected, _b64decode(parts[2])):
        raise ValueError("invalid token")
    header = json.loads(_b64decode(parts[0]))
    payload = json.loads(_b64decode(parts[1]))
    if header.get("alg") != "HS256" or header.get("typ") != "JWT":
        raise ValueError("invalid token")
    if not isinstance(payload.get("sub"), str) or int(payload["exp"]) <= int(datetime.utcnow().timestamp()):
        raise ValueError("expired token")
    return int(payload["sub"])


def require_auth(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        authorization = request.headers.get("Authorization", "")
        if not authorization.startswith("Bearer "):
            return jsonify({"error": "authentication required"}), 401
        try:
            user_id = decode_token(authorization[7:].strip())
        except (ValueError, TypeError, KeyError, json.JSONDecodeError, UnicodeDecodeError, binascii.Error):
            return jsonify({"error": "invalid or expired token"}), 401
        user = UserRepository(DATABASE).find_public_by_id(user_id)
        if user is None:
            return jsonify({"error": "invalid or expired token"}), 401
        g.user = user
        return view(*args, **kwargs)
    return wrapped


def create_task(title: str, owner_id: int) -> dict:
    return TaskRepository(DATABASE).create_for_owner(title, owner_id)


def get_tasks(owner_id: int):
    return TaskRepository(DATABASE).list_for_owner(owner_id)


def get_task(task_id: int, owner_id: int) -> dict | None:
    return TaskRepository(DATABASE).get_for_owner(task_id, owner_id)


def update_task(task_id: int, owner_id: int, title: str | None = None, status: str | None = None) -> dict | None:
    values = {}
    if title is not None:
        values["title"] = title
    if status is not None:
        values["status"] = status
    return TaskRepository(DATABASE).update_for_owner(task_id, owner_id, values)


init_db()


@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username") if isinstance(data, dict) else None
    password = data.get("password") if isinstance(data, dict) else None
    if not isinstance(username, str) or not username.strip() or not isinstance(password, str) or not password:
        return jsonify({"error": "username and password are required"}), 400
    username = username.strip()
    if find_user(username) is not None:
        return jsonify({"error": "username already exists"}), 409
    try:
        user = create_user(username, password)
    except IntegrityError:
        return jsonify({"error": "username already exists"}), 409
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username") if isinstance(data, dict) else None
    password = data.get("password") if isinstance(data, dict) else None
    user = find_user(username) if isinstance(username, str) and isinstance(password, str) else None
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid credentials"}), 401
    return jsonify({"token": create_token(user["id"]), "user": {"id": user["id"], "username": user["username"]}})


@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks():
    return jsonify(get_tasks(g.user["id"]))


@app.route("/tasks", methods=["POST"])
@require_auth
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title") if isinstance(data, dict) else None
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    return jsonify(create_task(title.strip(), g.user["id"])), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def show_task(task_id: int):
    task = get_task(task_id, g.user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        return jsonify({"error": "request body must be a JSON object"}), 400
    existing_task = get_task(task_id, g.user["id"])
    if existing_task is None:
        return jsonify({"error": "task not found"}), 404
    if "status" in data and data["status"] not in VALID_STATUSES:
        return jsonify({"error": "invalid status"}), 422
    if "title" in data and not isinstance(data["title"], str):
        return jsonify({"error": "title must be a string"}), 400
    task = update_task(task_id, g.user["id"], title=data.get("title"), status=data.get("status"))
    if existing_task["status"] != "completed" and data.get("status") == "completed":
        send_notification_email.delay(g.user["username"], task["title"])
    return jsonify(task)


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

